/*
 * Smoke test for the C bindings generated by SWIG's experimental C backend.
 * Plain C11, uses only the generated header.
 *
 * Usage: cosim_c_smoke <path to tests/data/msmi/OspSystemStructure.xml>
 */
#include "cosim_c_wrap.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int failures = 0;

#define CHECK(cond)                                                     \
    do {                                                                \
        if (!(cond)) {                                                  \
            fprintf(stderr, "%s:%d: CHECK failed: %s\n", __FILE__,      \
                __LINE__, #cond);                                       \
            ++failures;                                                 \
        }                                                               \
    } while (0)

/* Returns nonzero (and prints/clears it) if a C++ exception is pending. */
static int check_error(const char* where)
{
    cosim_SWIG_CException* ex = cosim_SWIG_CException_get_pending();
    if (!ex) return 0;
    fprintf(stderr, "%s: error %d: %s\n", where,
        cosim_SWIG_CException_code_get(ex), cosim_SWIG_CException_msg_get(ex));
    cosim_SWIG_CException_reset_pending();
    return 1;
}

static unsigned int find_ref(cosim_execution* exe, int sim, const char* name)
{
    cosim_model_description* md = cosim_execution_get_model_description(exe, sim);
    cosim_VariableDescriptionVector* vars = cosim_model_description_variables_get(md);
    unsigned int ref = (unsigned int)-1;
    for (size_t i = 0; i < cosim_VariableDescriptionVector_size(vars); ++i) {
        cosim_variable_description* v = cosim_VariableDescriptionVector_get(vars, (int)i);
        /* Ownership trap: string getters return a strdup()ed copy that the
         * caller must free(), despite the `const char*` return type. */
        const char* vname = cosim_variable_description_name_get(v);
        if (strcmp(vname, name) == 0) {
            ref = cosim_variable_description_reference_get(v);
        }
        free((void*)vname);
    }
    /* Note: `vars` and `v` are borrowed (owned by `md`), only `md` is ours. */
    cosim_model_description_delete(md);
    return ref;
}

int main(int argc, char** argv)
{
    if (argc != 2) {
        fprintf(stderr, "usage: %s <OspSystemStructure.xml>\n", argv[0]);
        return 2;
    }
    cosim_set_log_level(cosim_log_level_warning);

    /* --- Error path: exceptions become a pending SWIG_CException. */
    cosim_configured_execution* bad = cosim_load_execution_from_ssp("/nonexistent/system.ssp", NULL, "");
    CHECK(bad == NULL);
    cosim_SWIG_CException* ex = cosim_SWIG_CException_get_pending();
    CHECK(ex != NULL);
    if (ex) {
        printf("expected error: code=%d msg=%s\n",
            cosim_SWIG_CException_code_get(ex), cosim_SWIG_CException_msg_get(ex));
        cosim_SWIG_CException_reset_pending();
    }

    /* --- Load an OSP configuration. */
    cosim_configured_execution* le = cosim_load_execution_from_osp_config(argv[1], NULL);
    if (check_error("load_osp_config")) return 1;
    /* Borrowed: a member getter returns a pointer into `le`, which owns it.
     * Do NOT call cosim_execution_delete() on it (that would double free). */
    cosim_execution* exe = cosim_configured_execution_execution_get(le);

    cosim_StringIntMap* sims = cosim_configured_execution_simulators(le);
    CHECK(cosim_StringIntMap_size(sims) == 4);
    const int sim = cosim_StringIntMap_get(sims, "TrueIdentity");
    cosim_StringIntMap_delete(sims);

    const unsigned int integerIn = find_ref(exe, sim, "integerIn");
    const unsigned int integerOut = find_ref(exe, sim, "integerOut");
    CHECK(integerIn != (unsigned int)-1 && integerOut != (unsigned int)-1);

    /* --- Observer and manipulator. The C backend has no typed upcast
     *     functions: passing a derived object where a base is expected
     *     needs an explicit cast. */
    cosim_last_value_observer* obs = cosim_last_value_observer_new();
    cosim_override_manipulator* man = cosim_override_manipulator_new();
    cosim_execution_add_observer(exe, (cosim_observer*)obs);
    cosim_execution_add_manipulator(exe, (cosim_manipulator*)man);
    if (check_error("add observer/manipulator")) return 1;

    cosim_override_manipulator_override_integer_variable(man, sim, integerIn, 42);

    /* --- Run. */
    const double t0 = cosim_execution_current_time(exe);
    CHECK(cosim_execution_step(exe) > 0.0);
    CHECK(cosim_execution_simulate_until(exe, t0 + 0.01));
    if (check_error("simulate")) return 1;
    printf("time: %g -> %g\n", t0, cosim_execution_current_time(exe));

    cosim_ValueReferenceVector* refs = cosim_ValueReferenceVector_new();
    cosim_ValueReferenceVector_push_back(refs, integerOut);
    cosim_IntVector* values = cosim_last_value_observer_get_integer(obs, sim, refs);
    CHECK(cosim_IntVector_size(values) == 1);
    CHECK(cosim_IntVector_get(values, 0) == 42);
    printf("integerOut = %d\n", cosim_IntVector_get(values, 0));

    /* --- Factory functions replacing constructors. */
    cosim_fixed_step_algorithm* algo = cosim_fixed_step_algorithm_create(1e-3, 0);
    cosim_execution* exe2 = cosim_execution_new(0.0, (cosim_algorithm*)algo);
    CHECK(cosim_execution_current_time(exe2) == 0.0);

    /* --- Cleanup: every object returned by the API is owned by the caller. */
    cosim_execution_delete(exe2);
    cosim_fixed_step_algorithm_delete(algo);
    cosim_IntVector_delete(values);
    cosim_ValueReferenceVector_delete(refs);
    cosim_override_manipulator_delete(man);
    cosim_last_value_observer_delete(obs);
    cosim_configured_execution_delete(le); /* also releases `exe` */

    if (failures) {
        fprintf(stderr, "%d check(s) failed\n", failures);
        return 1;
    }
    printf("C smoke test OK\n");
    return 0;
}
